"""Trusted stateless control API; not code generated by an LLM."""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import math
import os
from urllib.parse import urlsplit


def calculate_quote(body, version=1):
    if not isinstance(body, dict):
        return 422, {"error": "invalid_request", "fields": ["body"]}
    allowed = {"quantity", "unit_price", "note", "tags"} | ({"currency"} if version == 2 else set())
    invalid = set(body) - allowed
    if version == 2 and body.get("currency") != "RUB":
        invalid.add("currency")
    quantity, price = body.get("quantity"), body.get("unit_price")
    if type(quantity) is not int or not 1 <= quantity <= (5 if version == 2 else 10):
        invalid.add("quantity")
    if type(price) not in (int, float) or not 0 <= price <= 1000 or not math.isfinite(price):
        invalid.add("unit_price")
    note, tags = body.get("note", ""), body.get("tags", [])
    if not isinstance(note, str) or len(note) > 12:
        invalid.add("note")
    if (not isinstance(tags, list) or len(tags) > 3
            or any(not isinstance(tag, str) or tag not in ("standard", "gift", "express") for tag in tags)):
        invalid.add("tags")
    if invalid:
        return 422, {"error": "invalid_request", "fields": sorted(invalid)}
    return 200, {**({"currency": "RUB"} if version == 2 else {}), "quantity": quantity, "unit_price": price,
                 "total": round(quantity * price, 2), "note": note, "tags": tags}


def reject_constant(value):
    raise ValueError("Nonfinite values are not JSON numbers")


def finite_float(value):
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError("Nonfinite JSON number")
    return parsed


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass

    def respond(self, status, body):
        data = json.dumps(body, allow_nan=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        self.respond(200 if self.path == "/health" else 404,
                     {"ready": True} if self.path == "/health" else {"error": "not_found"})

    def do_POST(self):
        version = int(os.getenv("CONTROL_API_VERSION", "1"))
        route = "/quote-v2" if version == 2 else "/quote"
        route = urlsplit(self.path).path
        if route not in (("/quote-v2", "/quote-v2/confirm") if version == 2 else ("/quote", "/quote/confirm")):
            self.respond(404, {"error": "not_found"})
            return
        try:
            size = int(self.headers.get("Content-Length", "0"))
            if not 0 <= size <= 65536:
                raise ValueError("Request exceeds limit")
            raw = self.rfile.read(size)
            body = json.loads(raw, parse_constant=reject_constant, parse_float=finite_float) if raw else None
            status, result = calculate_quote(body, version)
        except (ValueError, UnicodeError):
            body, status, result = None, 400, {"error": "invalid_json", "fields": []}
        fault = os.getenv("CONTROL_API_FAULT", "")
        if status == 200:
            if fault == "wrong_total":
                result["total"] += 1
            elif fault == "missing_required":
                result.pop("quantity")
            elif fault == "wrong_type":
                result["quantity"] = str(result["quantity"])
            elif fault == "story_goal" and route.endswith("/confirm"):
                result["total"] += 1
        elif status == 422 and fault == "error_fields_type":
            result["fields"] = [123]
        print(json.dumps({"method": "POST", "path": route, "body": body,
                          "status": status}, ensure_ascii=False, allow_nan=False), flush=True)
        self.respond(status, result)


if __name__ == "__main__":
    ThreadingHTTPServer(("0.0.0.0", 8080), Handler).serve_forever()
